"""Boolean expression toolkit (Python stdlib only).

Grammar (precedence: ! > & > |, all binary ops left-associative):

    expr    := term ('|' term)*
    term    := factor ('&' factor)*
    factor  := '!' factor | '(' expr ')' | IDENT | '0' | '1'

AST nodes are plain tuples:
    ('const', 0 or 1)
    ('var', name)
    ('not', child)
    ('and', left, right)
    ('or', left, right)
"""

__all__ = [
    "BoolExprSyntaxError",
    "parse",
    "eval_expr",
    "variables",
    "truth_table",
    "is_tautology",
    "is_contradiction",
]

MAX_VARIABLES = 20


class BoolExprSyntaxError(SyntaxError):
    """Parse error carrying the offending position in the source string."""

    def __init__(self, message, pos):
        super().__init__(f"{message} (position {pos})")
        self.pos = pos
        self.message = message


# ---------------------------------------------------------------------------
# Tokenizer
# ---------------------------------------------------------------------------

def _tokenize(text):
    """Return a list of (kind, value, pos) tokens. kind in {'ident','op','end'}."""
    tokens = []
    i = 0
    n = len(text)
    while i < n:
        c = text[i]
        if c.isspace():
            i += 1
            continue
        if c.isalpha() or c == "_":
            j = i + 1
            while j < n and (text[j].isalnum() or text[j] == "_"):
                j += 1
            tokens.append(("ident", text[i:j], i))
            i = j
            continue
        if c in "&|!()01":
            tokens.append(("op", c, i))
            i += 1
            continue
        raise BoolExprSyntaxError(f"unexpected character {c!r}", i)
    tokens.append(("end", None, n))
    return tokens


# ---------------------------------------------------------------------------
# Recursive-descent parser
# ---------------------------------------------------------------------------

class _Parser:
    def __init__(self, text):
        self.text = text
        self.tokens = _tokenize(text)
        self.index = 0

    def peek(self):
        return self.tokens[self.index]

    def advance(self):
        tok = self.tokens[self.index]
        self.index += 1
        return tok

    def expect_op(self, op):
        kind, value, pos = self.peek()
        if kind == "op" and value == op:
            return self.advance()
        raise BoolExprSyntaxError(f"expected {op!r}", pos)

    # expr := term ('|' term)*   -- lowest precedence
    def parse_expr(self):
        node = self.parse_term()
        while True:
            kind, value, pos = self.peek()
            if kind == "op" and value == "|":
                self.advance()
                node = ("or", node, self.parse_term())
            else:
                return node

    # term := factor ('&' factor)*
    def parse_term(self):
        node = self.parse_factor()
        while True:
            kind, value, pos = self.peek()
            if kind == "op" and value == "&":
                self.advance()
                node = ("and", node, self.parse_factor())
            else:
                return node

    # factor := '!' factor | '(' expr ')' | IDENT | '0' | '1'
    def parse_factor(self):
        kind, value, pos = self.advance()
        if kind == "op":
            if value == "!":
                return ("not", self.parse_factor())
            if value == "(":
                node = self.parse_expr()
                self.expect_op(")")
                return node
        elif kind == "ident":
            if value in ("0", "1"):
                return ("const", int(value))
            return ("var", value)
        raise BoolExprSyntaxError(
            f"expected an expression (got {value!r})", pos
        )


def parse(text):
    """Parse a boolean expression string into an AST tuple."""
    parser = _Parser(text)
    node = parser.parse_expr()
    kind, value, pos = parser.peek()
    if kind != "end":
        raise BoolExprSyntaxError(f"unexpected token {value!r}", pos)
    return node


# ---------------------------------------------------------------------------
# Evaluation and analysis
# ---------------------------------------------------------------------------

def eval_expr(ast, env):
    """Evaluate an AST under a mapping {variable_name: bool/int}."""
    op = ast[0]
    if op == "const":
        return ast[1]
    if op == "var":
        try:
            return bool(env[ast[1]])
        except KeyError:
            raise KeyError(f"unbound variable {ast[1]!r}") from None
    if op == "not":
        return not eval_expr(ast[1], env)
    if op == "and":
        return eval_expr(ast[1], env) and eval_expr(ast[2], env)
    if op == "or":
        return eval_expr(ast[1], env) or eval_expr(ast[2], env)
    raise ValueError(f"unknown AST node {op!r}")


def variables(ast):
    """Return variable names in first-appearance (left-to-right) order."""
    seen = []

    def walk(node):
        op = node[0]
        if op == "var":
            if node[1] not in seen:
                seen.append(node[1])
        elif op == "not":
            walk(node[1])
        elif op in ("and", "or"):
            walk(node[1])
            walk(node[2])

    walk(ast)
    return seen


def _iter_envs(names):
    """Yield one dict per assignment over `names`, last variable fastest."""
    for bits in range(1 << len(names)):
        yield {
            name: bool((bits >> (len(names) - 1 - i)) & 1)
            for i, name in enumerate(names)
        }


def truth_table(expr):
    """Yield rows ({variable: value}, result) for every assignment.

    `expr` may be a string (parsed first) or an already-built AST.
    Raises ValueError for more than MAX_VARIABLES distinct variables.
    """
    ast = parse(expr) if isinstance(expr, str) else expr
    names = variables(ast)
    if len(names) > MAX_VARIABLES:
        raise ValueError(
            f"expression has {len(names)} variables; "
            f"exhaustive enumeration supports at most {MAX_VARIABLES}"
        )
    for env in _iter_envs(names):
        yield dict(env), eval_expr(ast, env)


def is_tautology(expr):
    """True iff the expression evaluates to true for every assignment."""
    return all(result for _, result in truth_table(expr))


def is_contradiction(expr):
    """True iff the expression evaluates to false for every assignment."""
    return not any(result for _, result in truth_table(expr))

